"use client";

import { useCallback, useMemo, useState } from "react";

import { useMutation, useQuery } from "@tanstack/react-query";
import { format, parseISO } from "date-fns";
import { formatInTimeZone } from "date-fns-tz";
import { useDebounce } from "use-debounce";

import IconAdd from "@purplefish-ai/material-icons/icons/icon-add";
import IconDelete from "@purplefish-ai/material-icons/icons/icon-delete";
import IconSearch from "@purplefish-ai/material-icons/icons/icon-search";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@purplefish-ai/shadcn-ui/components/ui/alert-dialog";
import { Button } from "@purplefish-ai/shadcn-ui/components/ui/button";
import { Input } from "@purplefish-ai/shadcn-ui/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@purplefish-ai/shadcn-ui/components/ui/table";
import { toast } from "@purplefish-ai/shadcn-ui/components/ui/use-toast";

import { useTRPC } from "@/trpc/client";

import { AddTimeSlotModal } from "./add-time-slot-modal";

interface ParticipantAvailabilityContentProps {
  organizationId: string;
  participantId: string;
}

export function ParticipantAvailabilityContent({
  organizationId,
  participantId,
}: ParticipantAvailabilityContentProps) {
  const trpc = useTRPC();
  const [searchQuery, setSearchQuery] = useState("");
  const [isAddSlotOpen, setIsAddSlotOpen] = useState(false);
  const [deleteSlotId, setDeleteSlotId] = useState<string | null>(null);

  const [debouncedSearchQuery] = useDebounce(searchQuery, 300);

  // Fetch participant details and availability
  const {
    data: participantsData,
    isLoading,
    refetch,
  } = useQuery(
    trpc.availability.getParticipants.queryOptions({
      organizationId,
      page: 1,
      page_size: 100, // Get more to find our participant
    }),
  );

  // Find the specific participant
  const data = useMemo(() => {
    if (!participantsData || typeof participantsData === "symbol") {
      return null;
    }
    if ("participants" in participantsData && participantsData.participants) {
      return participantsData.participants.find(
        (p) => p.participant_id === participantId,
      );
    }
    return null;
  }, [participantsData, participantId]);

  // Delete time slot mutation
  const deleteSlotMutation = useMutation(
    trpc.availability.removeTimeslot.mutationOptions({
      onSuccess: () => {
        toast({
          title: "Time slot removed",
          description:
            "The availability time slot has been removed successfully.",
        });
        void refetch();
      },
      onError: () => {
        toast({
          title: "Error",
          description: "Failed to remove time slot. Please try again.",
          variant: "destructive",
        });
      },
    }),
  );

  const handleDeleteSlot = useCallback((timeslotId: string) => {
    setDeleteSlotId(timeslotId);
  }, []);

  const confirmDelete = useCallback(() => {
    if (deleteSlotId) {
      deleteSlotMutation.mutate({
        organizationId,
        participant_id: participantId,
        timeslot_id: deleteSlotId,
      });
      setDeleteSlotId(null);
    }
  }, [deleteSlotId, deleteSlotMutation, participantId, organizationId]);

  const handleSlotAdded = useCallback(() => {
    setIsAddSlotOpen(false);
    void refetch();
  }, [refetch]);

  // Filter time slots based on search
  const filteredSlots = useMemo(() => {
    if (!data || !("availability" in data) || !data.availability) {
      return [];
    }
    if (!debouncedSearchQuery) {
      return data.availability;
    }

    const searchLower = debouncedSearchQuery.toLowerCase();
    return data.availability.filter((slot) => {
      const startDate = format(parseISO(slot.start_time), "PPpp").toLowerCase();
      const endDate = format(parseISO(slot.end_time), "PPpp").toLowerCase();
      return startDate.includes(searchLower) || endDate.includes(searchLower);
    });
  }, [data, debouncedSearchQuery]);

  // Sort slots by start time
  const sortedSlots = useMemo(() => {
    return [...filteredSlots].sort(
      (a, b) =>
        new Date(a.start_time).getTime() - new Date(b.start_time).getTime(),
    );
  }, [filteredSlots]);

  // Default timezone - would ideally come from participant data
  const participantTimezone = "America/New_York";

  const formatDateTime = (dateString: string) => {
    try {
      return formatInTimeZone(
        parseISO(dateString),
        participantTimezone,
        "MMM dd, yyyy h:mm a",
      );
    } catch {
      return dateString;
    }
  };

  if (isLoading) {
    return <div>Loading participant data...</div>;
  }

  if (!data) {
    return <div>Participant not found</div>;
  }

  return (
    <>
      <div className="space-y-6">
        {/* Participant Info */}
        <div>
          <h1 className="mb-2 text-3xl font-bold">
            Availability for {"first_name" in data ? data.first_name : ""}{" "}
            {"last_name" in data ? data.last_name : ""}
          </h1>
          <div className="text-muted-foreground">
            <p>Email: {"email" in data ? data.email : ""}</p>
            <p>
              Phone:{" "}
              {"phone" in data && data.phone ? data.phone : "Not provided"}
            </p>
            <p>Timezone: {participantTimezone}</p>
          </div>
        </div>

        {/* Actions and Search */}
        <div className="flex items-center justify-between gap-4">
          <div className="max-w-md flex-1">
            <div className="relative">
              <IconSearch className="text-muted-foreground absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2" />
              <Input
                placeholder="Search time slots..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>
          </div>
          <Button onClick={() => setIsAddSlotOpen(true)} className="gap-2">
            <IconAdd className="h-4 w-4" />
            Add Time Slot
          </Button>
        </div>

        {/* Time Slots Table */}
        <div className="rounded-lg border">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Start Time</TableHead>
                <TableHead>End Time</TableHead>
                <TableHead>Duration</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {sortedSlots.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={4} className="py-8 text-center">
                    {debouncedSearchQuery
                      ? "No time slots match your search"
                      : "No availability time slots added yet"}
                  </TableCell>
                </TableRow>
              ) : (
                sortedSlots.map((slot) => {
                  const duration = Math.round(
                    (new Date(slot.end_time).getTime() -
                      new Date(slot.start_time).getTime()) /
                      (1000 * 60),
                  );
                  const hours = Math.floor(duration / 60);
                  const minutes = duration % 60;
                  const durationText =
                    hours > 0
                      ? `${hours}h ${minutes > 0 ? `${minutes}m` : ""}`
                      : `${minutes}m`;

                  return (
                    <TableRow key={slot.timeslot_id}>
                      <TableCell>{formatDateTime(slot.start_time)}</TableCell>
                      <TableCell>{formatDateTime(slot.end_time)}</TableCell>
                      <TableCell>{durationText}</TableCell>
                      <TableCell className="text-right">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDeleteSlot(slot.timeslot_id)}
                          className="text-destructive hover:text-destructive"
                        >
                          <IconDelete className="h-4 w-4" />
                        </Button>
                      </TableCell>
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>
        </div>

        {/* Summary */}
        <div className="text-muted-foreground text-sm">
          Total slots: {data.availability.length}
        </div>
      </div>

      {/* Add Time Slot Modal */}
      <AddTimeSlotModal
        open={isAddSlotOpen}
        onOpenChange={setIsAddSlotOpen}
        organizationId={organizationId}
        participantId={participantId}
        participantTimezone={participantTimezone}
        existingSlots={data.availability}
        onSlotAdded={handleSlotAdded}
      />

      {/* Delete Confirmation Dialog */}
      <AlertDialog
        open={deleteSlotId !== null}
        onOpenChange={(open) => !open && setDeleteSlotId(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Time Slot</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to remove this availability time slot? This
              action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDelete}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

