                    hours > 0
                      ? `${hours}h ${minutes > 0 ? `${minutes}m` : ""}`
                      : `${minutes}m`;

                  return (
                    <TableRow key={slot.timeslot_id}>
                      <TableCell>{formatDateTime(slot.start_time)}</TableCell>
                      <TableCell>{formatDateTime(slot.end_time)}</TableCell>
                      <TableCell>{durationText}</TableCell>
                      <TableCell className="text-right">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDeleteSlot(slot.timeslot_id)}
